{
["category"] = "Azshara",
["description"] = "Was?! Was?!\n\nDas war nicht gut genug für Euch? Wisst Ihr, wie teuer diese Sprengstoffe sind? Die kosten... ach, egal. Ihr wollt also echtes Geld machen, ja? Na denn... so läuft das im Geschäftsleben: Ihr beweist, dass Ihr ein wertvoller Angestellter seid, und dann werdet Ihr entsprechend belohnt, nachdem Ihr schön brav durchgehalten habt.\n\nFalls Ihr also ein 'wertvoller' Angestellter seid, dann begebt Euch zu den Ruinen von Eldarath und bringt mir irgendeine Rune, nach der diese Blutelfen gesucht haben. Anscheinend befindet sie sich im Besitz der Naga.",
["id"] = 5534,
["level"] = 53,
["objectiveText"] = "Sucht, in den Ruinen von Eldarath irgendeine Rune, die die Naga in ihrem Besitz haben, und bringt sie Kim'jal in Azshara.",
