},
{
["category"] = "Azshara",
["complete"] = true,
["description"] = "<Als Ihr seht, wie die Energien der Kristalle auf die Siegel eingestimmt sind, fragt Ihr Euch, ob das Zerstören eines Siegels, wodurch dessen Energie mit einem Schlag freigesetzt wird, auch den entsprechenden Kristall zerstören würde.\r\n\r\nMit den explosiven Ergebnissen wäre Euch Rimtoris Zorn sicher. Es würde außerdem die perfekte Gelegenheit bieten, sie anzugreifen, während sie aufgebracht ist.>",
["id"] = 91500,
