{
["category"] = "Brennende Steppe",
["complete"] = true,
["description"] = "Ich habe noch eine weitere kleine Bitte an Euch.\n\nMeine anfänglichen Studien bezüglich der Essenz, die Ihr gesammelt habt, haben ergeben, dass es wohl möglich ist, Großdrachenwelpen-Eier einzufrieren und so zu konservieren! Ich möchte diese Theorie überprüfen, aber zuerst benötige ich speziell angefertigte Komponenten der Ingenieurskunst. Mein Kollege Felnok Steelspring kann sie herstellen.\n\nHier, bringt Felnok diesen Brief. Darin steht, was ich benötige. Ihr findet Felnok in Winterspring in der Stadt Everlook.",
["id"] = 4808,
