{
["category"] = "Feralas",
["description"] = "Als Jäger strebe ich danach, die Stärken nachzuahmen, die ich bei meinen Gegnern sehe. Man kann den Kampf zu seinen Gunsten wenden, indem man einfach seinen Feind gut kennt, Brakk.\n\nAn einem Ort namens Teufelswald, nördlich von Ashenvale, wurden die Kreaturen durch eine Substanz, das so genannte Fel, verderbt. Die Bären und Wölfe wurden von ihr verrückt, allerdings glaube ich, dass sie dadurch auch noch stärker geworden sind.\n\nGeht, Brakk. Reist zum Teufelswald und tretet den Bestien gegenüber. Erfahrt selbst, ob sie wirklich so stark sind, wie ich glaube.",
["id"] = 4120,
["level"] = 52,
["objectiveText"] = "Talo Thornhoff im Camp Mojache in Feralas möchte, dass Ihr 12 Wutklauengrizzlys und 12 Teufelspfotenverheerer im Teufelswald erledigt.",
