{
["category"] = "Gefängnis von Alcaz",
["description"] = "Ich habe Euch ja gesagt, dass es sich für Euch lohnen wird, mich zu befreien. Ich habe zwar kein Gold für Euch, dafür aber etwas Besseres.\r\n\r\nNehmt das. Damit findet Ihr einen Schatz, der noch wertvoller ist als Gold. Macht damit, was Ihr wollt, aber falls jemand fragt, wo Ihr ihn herhabt, dann sagt Ihr ihm, dass diese Person tot ist.\r\n\r\nSagt ihm, dass der Spender von Drachenfeuer vernichtet und im Meer verstreut wurde.",
["id"] = 96337,
["level"] = 53,
["objectiveText"] = "Verwendet die von Mason Connery bereitgestellte Notiz, um seinen versteckten Schatz zu finden.",
