{
["category"] = "Maraudon",
["complete"] = true,
["description"] = "Ich hatte eine Vision.\r\n\r\nTief an dem Ort, der als Maraudon bekannt ist, hinter den Fällen des irdenen Gesangs, gibt es eine Kammer, die mit strahlend weißen Kristallen gefüllt ist und von mächtigen Riesen bewacht wird. An der höchsten Stelle dieser Kammer befindet sich ein Kristall von außergewöhnlicher Brillanz. Er ist ein Aspekt des Sonnengottes, das rechte Auge der Erdenmutter selbst: An'she.\r\n\r\nIch habe von seinem Glanz geträumt, und er ruft nach mir. Hexenmeister, entfernt An'shes Strahlen von diesem Ort und bringt es hierher, wo es hingehört: unter den freien Himmel von Mulgore.",
["id"] = 96776,
["level"] = 51,
["objectiveText"] = "Bergt den Kristall, der als An'shes Strahlen bekannt ist, aus Maraudon.",
["objectives"] = {
{
["finished"] = true,
["have"] = 1,
["need"] = 1,
["text"] = "An'shes Strahlen: 1/1",
},
},
["rewardMoney"] = 13781,
["rewardXP"] = 11900,
["title"] = "An'shes Strahlen",
},
{
["category"] = "Maraudon",
["complete"] = true,
["description"] = "Diese missratenen Zentauren - meine Söhne und Töchter - brauchen ihren Vater.\n\nSeht Euch um - dieser Ort hallt wider von Hoffnung und all jenem, was mein Vater Cenarius predigt. All das entsprang aus mir! Und ich kann ihnen das nicht nehmen... nicht einmal ob ihrer Verbrechen gegen mich.\n\nEines jedoch möchte ich von Euch erbitten, damit mein Bruder Ruhe findet. Nehmt dies... es ist das erste Samenkorn, das aus dem Leben entstand, das meine Überreste nährten. Sagt ihm, dass mein Geist hier bleibt und dass ich weiterlebe. Er wird es sicherlich verstehen.",
["id"] = 7066,
["level"] = 51,
["objectiveText"] = "Sucht Remulos in Moonglade auf und gebt ihm das Samenkorn des Lebens.",
["objectives"] = {
{
["finished"] = true,
["have"] = 1,
["need"] = 1,
["text"] = "Sucht Remulos in Moonglade auf und gebt ihm das Samenkorn des Lebens.",
},
},
["rewardMoney"] = 16125,
["rewardXP"] = 11900,
["title"] = "Samenkorn des Lebens",
},
{
["category"] = "Orgrimmar",
["complete"] = true,
["description"] = "Es scheint, als sei es die Absicht der Silithiden - nein, ihr ganzer Lebenszweck! -, alles zu verschlingen, was ihnen im Weg steht und was nicht zu ihrer eigenen Ökologie gehört. Nur darauf konzentrieren sie sich und darum stellen sie eine große Gefahr für alles Leben auf Azeroth dar.\n\nBis jetzt haben wir nur die Anfänge gesehen. Ich vermute, dass sie ihre Kraft aus einem Ort tiefer drinnen in Kalimdor beziehen: aus dem Un'Goro Krater. Geht nach Gadgetzan in der Tanariswüste und sprecht mit Alchimist Pestlezugg. Erzählt ihm von meiner Theorie; er wird uns bestimmt dabei helfen, die Silithiden zu bekämpfen.",
["id"] = 4494,
["level"] = 53,
["objectiveText"] = "Sprecht in Gadgetzan mit Alchimist Pestlezugg.",
["objectives"] = {
},
["rewardMoney"] = 0,
["rewardXP"] = 525,
["title"] = "Der Marsch der Silithiden",
},
{
["category"] = "Tanaris",
["complete"] = true,
["description"] = "Ich habe einst die furchteinflößenden Kammern des Versunkenen Tempels betreten. Das Böse an jenem Ort durchdringt alle, die eintreten. Mit Mühe und Not habe ich es geschafft, irgendwie meinen Weg wieder nach draußen zu finden, indem ich durch den Brühschlamm watete, der jetzt den Boden bedeckt. Ich kann mich nur daran erinnern, dass ich durch einen großen, kreisrunden Raum gestolpert bin, der angefüllt war mit Schlangenstatuen ...\n\nKürzlich habe ich einen runden Stein entdeckt, der anscheinend das gleiche Schlangensymbol trägt. Ich habe ihn verpackt und in meine Werkstatt nach Ratchet geschickt. Bringt ihn her und ich kann Euch vielleicht mehr erzählen.",
["id"] = 3444,
["level"] = 51,
["objectiveText"] = "Holt den runden Stein aus Marvon Rivetseekers Werkstatt in Ratchet.",
["objectives"] = {
{
["finished"] = true,
["have"] = 1,
["need"] = 1,
["text"] = "Steinkreis: 1/1",
},
},
["rewardMoney"] = 9188,
["rewardXP"] = 4900,
["title"] = "Der runde Stein",
},
{
["category"] = "Un'Goro-Krater",
["complete"] = true,
["description"] = "Seht, ich habe keine Ahnung, wie ich hierher kam. Niemand weiß das - niemand versteht es! Ich kann mich einfach an nichts erinnern...\n\nAber diese Gegenstände, die Ihr mir gebracht habt... Ich erinnere mich an etwas.\n\nMein Schwert. Ich soll es irgendwie stärken, aber ich weiß beim besten Willen nicht, warum. Es tut mir Leid, dass ich Euch nicht mehr sagen kann, aber ich kann mich einfach nicht erinnern!\n\nNa, egal, ich weiß aber, wo Ihr es hinbringen könnt: zu Donova Snowden in Winterspring. Ihr findet sie bei den Thermalquellen. Sie kann das Schwert an den Teichen dort aushärten.",
["id"] = 3908,
["level"] = 52,
["objectiveText"] = "Bringt Linkens Schwert zu Donova Snowden in Winterspring.",
["objectives"] = {
{
["finished"] = true,
["have"] = 1,
["need"] = 1,
["text"] = "Bringt Linkens Schwert zu Donova Snowden in Winterspring.",
},
},
["rewardMoney"] = 10200,
["rewardXP"] = 5100,
["title"] = "Es ist für jeden ein Geheimnis",
},
{
["category"] = "Un'Goro-Krater",
["description"] = "In diesem Krater gibt es viele seltsame Kreaturen - sie scheinen edler zu sein als ihre Verwandten, die man überall in meinem Heimatland und jenseits davon findet. Ich habe keine Erklärung dafür, aber dieser Ort trägt die Handschrift der Erdenmutter. Immer, wenn ich auf eines ihrer wundervollen Geschöpfe in diesem Krater stoße, erweise ich ihr meine Ehrerbietung.\n\nWenn auch Ihr diese Erleuchtung spüren möchtet, die eine solche Tat begleitet, dann geht nach Norden. Dort findet Ihr große Affen, die die Kraft eines jeden Sterblichen auf eine harte Probe stellen. Bringt mir ihre Pelze ... beweist mir Eure Kraft.",
["id"] = 4289,
["level"] = 55,
