{
["category"] = "Un'Goro-Krater",
["description"] = "Als Lehrling von Marvon Rivetseeker habe ich unglaublich viel gelernt. Aber er ist jetzt schon sehr lange fort. Daher denke ich, werde ich an ein paar eigenen Experimenten arbeiten.\n\nIch habe kürzlich etwas über den Un'Goro Krater gelesen und über die eigentümliche Vulkanaktivität, die in der Mitte des Kraters zu erkennen ist. Ich glaube, ich könnte eine Menge lernen, wenn ich nur etwas Asche von den Elementaren dort haben könnte.\n\nWürde es Euch etwas ausmachen, etwas Asche für mich einzusammeln, falls Ihr dort entlangkommen solltet?",
["id"] = 4502,
["level"] = 55,
["objectiveText"] = "Sammelt 9 Proben Un'Goro-Asche von den Feuerelementare am Vulkan im Un'Goro Krater ein und bringt die Proben zu Liv Rizzlefix in Ratchet.",
["objectives"] = {
