["title"] = "Ein Köder für Lar'korwi",
},
{
["category"] = "Undercity",
["description"] = "Seht Ihr die Tauren hinter mir - diejenige, die aussieht, als müsste sie sich jeden Moment übergeben? Sie war erst vor kurzem in Azshara. Sie behauptet, dass sie von einigen Naga verwundet wurde, als sie sich den Weg durch die Ruinen von Eldarath bahnte.\n\nNachdem sie einige von ihnen zurückschlagen konnte, machte sie eine Pause am Strand und trank aus einem der Gezeitenteiche. Jetzt ist ihr ein wenig übel ... unter anderem.\n\nIch würde gern herausfinden, was sie getrunken hat. Nehmt diesen Kasten, darin befinden sich einige leere Phiolen, die ich mit Etiketten versehen habe. Füllt jede an einem anderen Teich und kehrt dann zurück.",
