{
["category"] = "Hexenmeister",
["description"] = "MALGRUK, ein Wichtel im Teufelswald namens Impsy hat nach Euch verlangt. Seine Bitte ist etwas merkwürdig, da er möchte, dass Ihr ihm ein Stück Teufelsstoff als Zeichen des \"guten Willens\" bringt. Bedenkt man die Macht, die Ihr bereits als Hexenmeister besitzt, kann ich nur vermuten, dass Ihr wisst, dass die Satyrn des Teufelswalds diesen Teufelsstoff bei sich tragen.\n\nIhr findet Impsy nördlich der Blutgiftfälle, von denen ich hörte, dass sie um diese Jahreszeit recht schön sein sollen.",
